"""Measured text and surface leaves; no previous library styles are imported."""
from write_elements import write
import sys

def card(name='접수 기준',note='주요 채널의 문의 기록을 분류해 반복 접수 원인을 찾고 담당 조직과 처리 기한을 합의합니다.',cls='',mark=False):return '<div class="card '+cls+'" DATA><div class="parts">'+('<span class="mark"><span class="icon" data-icon="chart-column-increasing"></span></span>' if mark else '')+'<p class="name">'+name+'</p><p class="note">'+note+'</p></div></div>'
def itemlist(n=5,div=False):
 names=['채널 현황 확인','담당 범위 합의','예산 배분 검토','개선 과제 승인','운영 이력 점검','현장 의견 취합'];notes=['반복 문의를 채널별로 분류하고 접수 빈도와 처리 시간을 대조합니다.','부서별 담당 범위를 확정해 이관 과정의 누락을 줄입니다.','확보한 예산을 배포 일정에 맞춰 배정하고 집행 항목을 정리합니다.']
 return '<div class="list '+('divided' if div else 'num')+'" DATA>'+''.join('<div class="item"><p class="name">'+names[i%6]+'</p>'+(''if div else'<p class="note">'+notes[i%3]+'</p>')+'</div>' for i in range(n))+'</div>'

CSS_CARD='''/* Replica18:576×101 pale card; rule at155px,32px title inset and183px note start.
Replica11:364×142 mark/centred-accent cards;14/19:stacked quiet captions. */
ROOT{container-type:size;container-name:od-card;display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;color:var(--ink)}
ROOT>.parts{container-type:inline-size;position:relative;display:grid;grid-template-columns:minmax(0,26.91%) minmax(0,1fr);gap:0;align-items:center;inline-size:min(100%,576px);min-height:0;min-block-size:min(100%,101px);max-block-size:100%;padding:0;background:var(--n-1);border-radius:var(--onboard-docket-card-radius);min-width:0}
ROOT>.parts:has(>.name):has(>.note)::before{content:"";position:absolute;left:26.91%;top:18%;height:64%;width:1px;background:var(--n-4)}
ROOT>.parts>.name{margin:0;padding:0 calc(var(--gap-sm)*.8) 0 calc(var(--pad)*4/3);font-size:clamp(var(--type-14),calc(3.299cqw),var(--type-20));font-weight:var(--name-weight);line-height:var(--body-line);letter-spacing:var(--name-track);color:var(--a2-7);word-break:keep-all;overflow-wrap:anywhere;min-width:0}
ROOT>.parts>.note{margin:0;padding:0 calc(var(--pad)*23/24) 0 calc(var(--pad)*7/6);font-size:clamp(var(--type-12),calc(2.778cqw),var(--type-16));font-weight:var(--body-weight);line-height:var(--onboard-docket-detail-line);letter-spacing:var(--body-track);color:var(--n-7);overflow-wrap:anywhere;min-width:0}
ROOT>.parts>.kick{grid-column:1 / -1;margin:0;padding:var(--gap-sm) var(--pad) 0;font-size:var(--type-12);line-height:var(--label-line);letter-spacing:var(--label-track);font-weight:var(--label-weight);color:var(--n-7)}ROOT>.parts>.fig{margin:0;padding:var(--gap-sm);font-size:clamp(var(--type-20),calc(7cqw),var(--type-40));font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track)}ROOT>.parts>.fig>small{font-size:var(--type-14)}
ROOT>.parts>.mark{width:64px;height:64px;display:flex;align-items:center;justify-content:center;font-size:var(--type-28);font-weight:var(--figure-weight);line-height:var(--figure-line);color:var(--ink)}ROOT>.parts>.mark>.icon{width:90%;height:90%}ROOT>.parts>.mark>.icon>svg{width:100%;height:100%}ROOT>.parts>.mark>.seat{width:58px;height:60px;aspect-ratio:1}
ROOT>.parts:has(>.mark){inline-size:min(100%,364px);grid-template-columns:minmax(0,1fr) 64px;grid-template-rows:calc(var(--type-22)*var(--body-line)) minmax(0,1fr);gap:calc(var(--gap-sm)/2) var(--gap-sm);padding:calc(var(--gap-sm)*17/14) calc(var(--pad)*7/6);min-block-size:min(100%,142px);block-size:auto;align-items:start}ROOT>.parts:has(>.mark)::before{display:none}ROOT>.parts:has(>.mark)>.mark{grid-column:2;grid-row:1 / 3;align-self:end}ROOT>.parts:has(>.mark)>.name,ROOT>.parts:has(>.mark)>.note,ROOT>.parts:has(>.mark)>.fig{grid-column:1;padding:0}ROOT>.parts:has(>.mark)>.name{color:var(--n-8);font-size:clamp(var(--type-16),calc(7.143cqw),var(--type-24));font-weight:var(--body-weight)}ROOT>.parts:has(>.mark)>.note{color:var(--ink);font-size:clamp(var(--type-12),calc(5.195cqw),var(--type-18));line-height:var(--body-line)}
ROOT.on>.parts{background:var(--a1-1-soft);color:var(--a1-7)}ROOT.on>.parts>.note{color:var(--a1-7)}ROOT.on>.parts>.name{color:inherit}ROOT.on>.parts:not(:has(>.name)){grid-template-columns:1fr;inline-size:min(100%,364px);min-block-size:min(100%,142px);padding:var(--gap-sm) var(--pad)}ROOT.on>.parts:not(:has(>.name))>.note{padding:0;text-align:center;font-size:clamp(var(--type-14),calc(5.38cqw),var(--type-18));font-weight:var(--onboard-docket-emphasis-weight);line-height:var(--body-line);letter-spacing:var(--label-track)}
ROOT.line>.parts{background:var(--page);border:var(--stroke) solid var(--n-4)}ROOT.quiet>.parts{inline-size:min(100%,279px);background:var(--n-1);border-radius:var(--radius-sm);grid-template-columns:minmax(0,1fr);row-gap:calc(var(--gap-sm)*3/14);min-block-size:min(100%,90px);padding:calc(var(--gap-sm)*9/14) calc(var(--pad)*5/6)}ROOT.quiet>.parts::before{display:none}ROOT.quiet>.parts>.name{color:var(--n-8);padding:0;font-size:var(--type-14);font-weight:var(--name-weight);line-height:var(--body-line)}ROOT.quiet>.parts>.note{padding:0;font-size:clamp(var(--type-12),calc(5.44cqw),var(--type-14));line-height:var(--onboard-docket-caption-line)}ROOT.quiet>.parts:not(:has(>.name)){inline-size:min(100%,311px);min-block-size:min(100%,117px);padding:calc(var(--gap-sm)*1.5) calc(var(--pad)*9/8)}ROOT.quiet>.parts:not(:has(>.name))>.note{font-size:clamp(var(--type-12),calc(6.226cqw),var(--type-16));line-height:var(--onboard-docket-quote-line)}
ROOT>.parts:not(:has(>.name)){grid-template-columns:1fr}ROOT>.parts:not(:has(>.name))>.note{grid-column:1}ROOT.tone-1>.parts{background:var(--n-1)}ROOT.tone-1>.parts>.name{color:var(--a1-7)}ROOT.tone-2>.parts{background:var(--a2-1-soft)}ROOT.tone-3>.parts{background:var(--a3-1-soft)}ROOT.tone-4>.parts{background:var(--a4-1-soft)}ROOT.tone-5>.parts{background:var(--n-2)}
@container od-card (max-width:400px){ROOT:not(.quiet)>.parts:not(:has(>.mark)):not(:has(>.fig)):has(>.name){display:flex;flex-direction:column;align-items:flex-start;gap:calc(var(--gap-sm)/2);padding:min(5cqw,var(--pad));justify-content:center}ROOT>.parts:not(:has(>.mark))::before{display:none}ROOT:not(.quiet)>.parts:not(:has(>.mark)):not(:has(>.fig))>.name{padding:0;font-size:var(--type-16)}ROOT:not(.quiet)>.parts:not(:has(>.mark)):not(:has(>.fig)):has(>.name)>.note{padding:0;font-size:var(--type-12)}ROOT>.parts>.fig{font-size:var(--type-28)}}
@container od-card (max-width:300px){ROOT>.parts:has(>.mark){display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-start;gap:calc(var(--gap-sm)/2);padding:min(5cqw,var(--pad));block-size:min(100%,244px)}ROOT>.parts:has(>.mark)>.mark{order:-1;width:48px;height:48px;flex:none}ROOT>.parts:has(>.mark)>.name{color:var(--n-8);font-size:var(--type-16)}ROOT>.parts:has(>.mark)>.note{color:var(--ink);font-size:var(--type-12)}}
@container od-card (max-width:450px) and (min-height:180px){ROOT.quiet>.parts:has(>.name){block-size:min(100%,160px);grid-template-rows:calc(var(--type-14)*var(--body-line)*2) minmax(0,1fr);align-content:stretch}ROOT.quiet>.parts:has(>.name)>.name,ROOT.quiet>.parts:has(>.name)>.note{align-self:start}}
@container od-card (max-height:90px){ROOT>.parts>.kick{display:none}ROOT>.parts>.mark{width:32px;height:32px}ROOT>.parts>.name{font-size:var(--type-14)}ROOT>.parts>.note{font-size:var(--type-12)}}
@container od-card (max-width:300px) and (max-height:140px){ROOT:not(.quiet)>.parts>.note{display:none}}
'''
CSS_CARD+='@container od-card (max-height:70px){ROOT.quiet>.parts:has(>.name){padding:calc(var(--gap-sm)/2);row-gap:0}ROOT.quiet>.parts:has(>.name)>.name{font-size:var(--type-12);line-height:var(--label-line)}ROOT.quiet>.parts:has(>.name)>.note{display:none}}'
CSS_CARD+='ROOT.quiet>.parts:has(>.kick){inline-size:min(100%,576px);block-size:min(100%,160px);grid-template-rows:var(--type-16) calc(var(--type-14)*var(--body-line)*2) minmax(0,1fr);align-content:stretch}ROOT.quiet>.parts:has(>.kick)>.kick{padding:0}ROOT.quiet>.parts:has(>.kick)>.name,ROOT.quiet>.parts:has(>.kick)>.note{align-self:start}'

CSS_CARD+='''
ROOT>.parts:has(>.fig){display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:var(--type-16) var(--type-48) calc(var(--type-18)*var(--body-line)*2) minmax(0,1fr);align-items:start;align-content:stretch;block-size:min(100%,244px);gap:calc(var(--gap-sm)/2);padding:var(--pad)}ROOT>.parts:has(>.fig)::before{display:none}ROOT>.parts:has(>.fig)>.kick{grid-row:1;padding:0}ROOT>.parts:has(>.fig)>.fig{grid-row:2;padding:0;font-size:var(--type-32)}ROOT>.parts:has(>.fig)>.name{grid-row:3;padding:0;font-size:var(--type-18)}ROOT>.parts:has(>.fig)>.note{grid-row:4;padding:0;font-size:var(--type-12)}ROOT>.parts:has(>.mark):has(>.kick){inline-size:min(100%,576px);block-size:min(100%,244px);grid-template-rows:var(--type-16) calc(var(--type-24)*var(--body-line)*2) minmax(0,1fr)}ROOT>.parts:has(>.mark):has(>.kick)>.kick{grid-column:1;grid-row:1;padding:0}ROOT>.parts:has(>.mark):has(>.kick)>.name{grid-column:1;grid-row:2}ROOT>.parts:has(>.mark):has(>.kick)>.note{grid-column:1;grid-row:3}ROOT>.parts:has(>.mark):has(>.kick)>.mark{grid-column:2;grid-row:1 / 4}@container od-card (max-width:300px){ROOT>.parts:has(>.mark):has(>.kick){display:flex;flex-direction:column;justify-content:flex-start}}'''

CSS_LIST='''/* Replica07:977×354 numbered split capsules,54px row and75px pitch.
Replica16:separate plain item rows with61px pitch and inset dividers. */
ROOT{container-type:size;container-name:od-list;display:grid;grid-auto-rows:minmax(0,1fr);gap:calc(var(--gap)*1.05);align-content:center;padding:0;inline-size:min(100%,977px);block-size:min(100%,calc(var(--od-list-count)*54px + (var(--od-list-count) - 1)*var(--gap)*1.05));align-self:center;justify-self:center;min-width:0;min-height:0;color:var(--ink);counter-reset:od-item;--od-list-count:5}
ROOT>.item{counter-increment:od-item;position:relative;display:grid;grid-template-columns:31% minmax(0,1fr);gap:var(--gap);align-items:center;min-width:0;min-height:0;max-height:54px;background:var(--n-1);border-radius:999px}
ROOT>.item>.name{align-self:stretch;display:flex;align-items:center;justify-content:center;margin:0;border-radius:999px;background:var(--a1);color:var(--a1-on);padding:calc(var(--gap-sm)/2);font-size:clamp(var(--type-12),calc(2.149cqw),var(--type-22));font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);word-break:keep-all;overflow-wrap:anywhere;min-width:0}
ROOT>.item:nth-child(even)>.name{background:var(--a2-7);color:var(--page)}ROOT.num>.item>.name::before{content:counter(od-item,decimal-leading-zero)'.';margin-right:var(--gap-sm);white-space:nowrap}
ROOT>.item>.note{margin:0;padding-right:var(--gap);font-size:clamp(var(--type-12),calc(1.9cqw),var(--type-20));font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-8);overflow-wrap:anywhere;min-width:0}
ROOT.divided{padding:0;gap:0;inline-size:min(100%,261px);block-size:min(100%,calc((var(--od-list-count) - 1)*61px + 33.6px));grid-template-rows:repeat(calc(var(--od-list-count) - 1),minmax(0,1fr)) auto}ROOT.divided>.item{display:flex;align-items:flex-start;gap:var(--gap-sm);background:none;border-radius:0;border-bottom:0;max-height:none;font-size:clamp(var(--type-14),calc(8.046cqw),var(--type-22))}ROOT.divided>.item:not(:last-child)::after{content:"";position:absolute;left:0;right:0;top:calc(var(--body-line)*1em + var(--gap-sm)/4);height:1px;background:var(--n-4)}ROOT.divided>.item>.name{justify-content:flex-start;align-self:flex-start;background:none;color:var(--ink);padding:0;font-weight:var(--body-weight);font-size:clamp(var(--type-14),calc(8.046cqw),var(--type-22));line-height:var(--body-line)}ROOT.divided>.item>.name::before{content:'';width:5px;height:5px;border-radius:50%;background:currentColor;flex:none;margin-right:var(--gap-sm)}ROOT.divided>.item>.note{display:none}
ROOT:not(.num):not(.check)>.item>.name::before{content:'';width:5px;height:5px;border-radius:50%;background:currentColor;flex:none;margin-right:var(--gap-sm)}
ROOT.check>.item>.name::before{content:'';background:none;border-radius:0;flex:none;width:12px;height:7px;border-left:2px solid currentColor;border-bottom:2px solid currentColor;transform:rotate(-45deg);margin-right:var(--gap-sm)}
@container od-list (max-width:600px){ROOT>.item{grid-template-columns:42% minmax(0,1fr);gap:var(--gap-sm)}ROOT>.item>.name{font-size:var(--type-14)}ROOT>.item>.note{font-size:var(--type-12);padding-right:calc(var(--gap-sm)/2)}ROOT.num>.item>.name::before{margin-right:calc(var(--gap-sm)/3)}}
@container od-list (max-width:360px){ROOT>.item{display:flex;background:none;gap:0}ROOT>.item>.name{width:100%;font-size:var(--type-14)}ROOT>.item>.note{display:none}}
@container od-list (max-height:320px){ROOT:not(.divided)>.item>.name{font-size:var(--type-12);line-height:var(--label-line);padding:1px calc(var(--gap-sm)/2);grid-column:1 / -1;width:100%}ROOT>.item>.note{display:none}ROOT.divided>.item>.name{padding:0}}
@container od-list (max-height:230px){ROOT.divided>.item{font-size:var(--type-14)}ROOT.divided>.item>.name{font-size:var(--type-14);line-height:var(--label-line)}}
'''

for count in range(1,13):CSS_LIST+=f'ROOT:has(>.item:nth-child({count}):last-child){{--od-list-count:{count}}}'
CSS_LIST+='ROOT.divided:has(>.item:nth-child(1):last-child),ROOT.divided:has(>.item:nth-child(2):last-child){grid-template-rows:repeat(var(--od-list-count),minmax(0,1fr))}'

def author(leaf):
 if leaf=='card':write(leaf,'card',CSS_CARD,'A quiet rounded surface separates a narrow name bay from the explanatory bay with an inset vertical rule. An optional mark belongs to the same card and moves to a compact upper row when narrow; accent and quiet variants retain the measured paper language.',[('replica-18','3x3',card()),('replica-11-on','4x3','<div class="card on" DATA><div class="parts"><p class="note">담당자가 채널별 변경 사항을 대조하고 승인 근거를 명확히 남깁니다.</p></div></div>'),('replica-11-mark','4x3',card('응답 품질 개선','검토한 변경 사항을 담당 조직에 전달하고 승인 근거를 함께 남깁니다.','',True)),('replica-14','3x3',card('지연 원인','지연 기록을 대조해 우선 조치할 구간을 정합니다.','quiet')),('replica-19','3x3','<div class="card quiet" DATA><div class="parts"><p class="note">담당 인력이 접수 기록을 분석해 반복 이슈의 발생 지점을 문서에 남깁니다.</p></div></div>'),('replica-08-tone-1','3x3',card('운영 원칙','합의한 기준을 담당 조직에 안내하고 적용 근거를 문서에 기록합니다.','tone-1')),('mark-long','5x4',card('주문 처리 안정성 검토','상담 채널에서 확인한 오류 원인을 분류하고 배포 일정과 담당자 합의 내역을 회의록에 남깁니다.','line',True))])
 elif leaf=='list':write(leaf,'list',CSS_LIST,'Numbered split capsules reproduce the54px rows of replica07. Their filled name bays alternate accent roles while the note continues on the pale capsule. The divided variant removes the capsule and uses inset rules and a restrained dot.',[('replica-07','6x3',itemlist()),('replica-16','3x3',itemlist(5,True)),('six-long','6x4',itemlist(6)),('checked-review','4x3',itemlist(3,True).replace('list divided','list divided check'))])
 else:raise SystemExit(leaf)

if __name__=='__main__':author(sys.argv[1])
